-- Session-local helpers. Run as the existing migration owner; never expose RPCs.
CREATE OR REPLACE FUNCTION pg_temp.exporural_state(p uuid, ids uuid[])
RETURNS jsonb LANGUAGE sql AS $state$
SELECT jsonb_build_object(
 'project',(SELECT to_jsonb(x) FROM public.map_projects x WHERE id=p),
 'segment',(SELECT to_jsonb(x) FROM public.map_segments x WHERE project_id=p AND slug='exporural'),
 'entities',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.map_entities x WHERE project_id=p AND (ids IS NULL OR id=ANY(ids))),'[]'),
 'geometries',coalesce((SELECT jsonb_agg(to_jsonb(x)-'native_geometry' ORDER BY x.id) FROM public.map_entity_geometries x WHERE project_id=p AND (ids IS NULL OR entity_id=ANY(ids))),'[]'),
 'geometry_versions',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.map_geometry_versions x WHERE project_id=p AND (ids IS NULL OR entity_id=ANY(ids))),'[]'),
 'lots',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.commercial_lots x WHERE project_id=p AND (ids IS NULL OR entity_id=ANY(ids))),'[]'),
 'rules',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.commercial_price_rules x WHERE project_id=p OR project_id IS NULL),'[]'),
 'prices',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_prices x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'overrides',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.commercial_lot_price_overrides x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'reservations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_reservations x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'negotiations',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_negotiations x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'sales',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_sales x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'orders',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_sale_orders x WHERE x.project_id=p AND (ids IS NULL OR x.id IN (SELECT i.order_id FROM public.lot_sale_order_items i JOIN public.commercial_lots l ON l.id=i.lot_id WHERE l.entity_id=ANY(ids)))),'[]'),
 'items',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_sale_order_items x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'installments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_sale_installments x JOIN public.lot_sale_orders o ON o.id=x.order_id WHERE o.project_id=p AND (ids IS NULL OR o.id IN (SELECT i.order_id FROM public.lot_sale_order_items i JOIN public.commercial_lots l ON l.id=i.lot_id WHERE l.entity_id=ANY(ids)))),'[]'),
 'contracts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_contracts x WHERE x.id IN (SELECT c.id FROM public.lot_contracts c JOIN public.commercial_lots l ON l.id=c.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids)) UNION SELECT cl.contract_id FROM public.lot_contract_lots cl JOIN public.commercial_lots l ON l.id=cl.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids)))),'[]'),
 'contract_lots',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.contract_id,x.lot_id) FROM public.lot_contract_lots x JOIN public.commercial_lots l ON l.id=x.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids))),'[]'),
 'contract_versions',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.lot_contract_versions x WHERE x.contract_id IN (SELECT c.id FROM public.lot_contracts c JOIN public.commercial_lots l ON l.id=c.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids)) UNION SELECT cl.contract_id FROM public.lot_contract_lots cl JOIN public.commercial_lots l ON l.id=cl.lot_id WHERE l.project_id=p AND (ids IS NULL OR l.entity_id=ANY(ids)))),'[]'),
 'lineage',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.map_lot_lineage x WHERE x.source_lot_id IN (SELECT id FROM public.commercial_lots WHERE project_id=p AND (ids IS NULL OR entity_id=ANY(ids))) OR x.target_lot_id IN (SELECT id FROM public.commercial_lots WHERE project_id=p AND (ids IS NULL OR entity_id=ANY(ids)))),'[]')
);
$state$;

CREATE OR REPLACE FUNCTION pg_temp.exporural_business(s jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT s-'project'-'segment'-'entities'-'geometries'-'geometry_versions'-'lots'-'rules'-'prices'-'lineage';
$$;

-- User-requested apron at Johan/Ubiretama. Existing commercial faces are immutable.
DO $surface$
DECLARE p uuid:='0538d132-34dd-4347-a33c-526edac7339c';
 seg uuid:='feb6fcb7-5bc4-4725-ad74-d408a7b56522';
 rev text:='2028-exporural-2026-10-21.surfaces.1';
 e uuid:='0769e76c-4ccb-4e01-9a08-751ba8fa757c'; sid uuid; before_state jsonb; ids uuid[]; after_state jsonb;
 pavement jsonb:=$pavement${"type":"Polygon","coordinates":[[[54.22954158,-12.625596249],[52.158197409,-5.981710073],[52.913714128,-5.74322223],[56.924777296,-18.178535932],[56.92538963990493,-20.548598352380136],[56.929622712,-20.548598352380136],[56.929622712,-28.24576617514732],[56.927378327528075,-28.24576617514732],[56.929622712,-36.932602528],[56.141195456,-36.941553583],[55.96260473572609,-28.24576617514732],[55.78109626024894,-28.24576617514732],[55.775158221894,-28.181148599330594],[55.756316689158254,-28.08290380111922],[55.72842772633281,-27.988287656044644],[55.691972732232216,-27.8977630110414],[55.647433105670984,-27.811792713044007],[55.5952902454636,-27.730839608986987],[55.53602555042461,-27.655366545804867],[55.47012041936851,-27.585836370432162],[55.398056251109836,-27.522711929803407],[55.320314444463094,-27.466456070853116],[55.23737639824279,-27.417531640515815],[55.149723511263446,-27.376401485726028],[55.057837182339554,-27.343528453418276],[54.962198810285685,-27.31937539052708],[54.962198810285685,-26.42167396523615],[55.070267327990194,-26.422013040407922],[55.08541072467372,-23.486471961382794],[55.07047908364582,-26.422010366799125],[55.09244558611701,-26.42143285757333],[55.114051610351126,-26.41979297820571],[55.135473180226825,-26.41710288189713],[55.1566745639671,-26.41337739545725],[55.177620029794966,-26.40863134569573],[55.198273845933414,-26.402879559422228],[55.2186002806055,-26.39613686344641],[55.23856360203419,-26.388418084577935],[55.258128078442525,-26.37973804962646],[55.2772579780535,-26.37011158540165],[55.29591756909012,-26.359553518713163],[55.31407111977542,-26.34807867637066],[55.331682898332375,-26.3357018851838],[55.348717172984024,-26.322437971962238],[55.36513821195338,-26.308301763515647],[55.381003194806695,-26.293550193632573],[55.49855994740139,-26.17589087091431],[55.85540700154425,-25.633407455064276],[56.13328128649171,-24.989573369524607],[56.353749343438864,-24.210876170989447],[56.55701013182622,-23.25826759136884],[56.633205199851886,-22.51915280749151],[56.64167171563123,-22.053039286419764],[56.630019605715404,-21.941298247650852],[56.630019605715404,-21.94129824765085],[56.58119642996448,-21.473095285799758],[56.48272930901251,-20.915849512566357],[56.47410856989251,-20.877323221249778],[56.46232779948778,-20.840274881279758],[56.44750418431707,-20.80481958101068],[56.42980244717005,-20.77109665910043],[56.40938731083638,-20.739245454206895],[56.38642349810573,-20.70940530498796],[56.36107573176777,-20.68171555010152],[56.33350873461214,-20.65631552820545],[56.30388722942851,-20.633344577957647],[56.272375939006565,-20.612942038015987],[56.23913958613595,-20.595247247038365],[56.20434289360634,-20.580399543682663],[56.16815058420738,-20.568538266606765],[56.13072738072876,-20.559802754468567],[56.09223800596011,-20.55433234592595],[56.05247844185784,-20.551860548123788],[55.10053575763166,-20.548598352380136],[56.40777454828182,-20.548598352380136],[56.40606959206033,-20.540389063777194],[56.416594480720185,-20.548598352380136],[56.505225205690856,-20.548598352380136],[55.708903414,-16.714344237],[54.22954158,-12.625596249]]]}$pavement$::jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('commercial-map:exporural:'||p,0));
 IF EXISTS(SELECT 1 FROM public.map_reference_migration_snapshots WHERE project_id=p AND source_revision=rev AND status='APPLIED') THEN RETURN; END IF;
 LOCK TABLE public.map_entities,public.map_entity_geometries,public.commercial_lots IN SHARE ROW EXCLUSIVE MODE;
 IF NOT EXISTS(SELECT 1 FROM public.map_segments WHERE id=seg AND project_id=p AND source_reference='2028-exporural-2026-10-20.1' AND is_active) THEN RAISE EXCEPTION 'OFFICIAL_REVISION_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.map_entity_geometries WHERE entity_id=e AND is_current AND version=4 AND geometry=$previous${"coordinates":[[[55.708903414,-16.714344237],[54.22954158,-12.625596249],[52.158197409,-5.981710073],[52.913714128,-5.74322223],[56.924777296,-18.178535932],[56.929622712,-36.932602528],[56.141195456,-36.941553583],[55.941576833,-27.221893426],[56.281127545,-24.629947745],[56.439418861,-24.075886813],[56.208617352,-24.88375235],[56.12716043723425,-25.070682641712487],[56.14166518247063,-24.9599612960025],[56.353749343438864,-24.210876170989447],[56.55701013182622,-23.25826759136884],[56.633205199851886,-22.51915280749151],[56.64167171563123,-22.053039286419764],[56.630019605715404,-21.941298247650852],[56.63056663412838,-21.89376060767769],[56.60684825864267,-21.719090389135445],[56.58884443013571,-21.546437838334104],[56.59896588437627,-21.469176156730637],[56.52438381808722,-21.110066814664076],[56.523257979157556,-21.103503018681707],[56.48932412488483,-20.853602527545583],[56.45677800981964,-20.775925877478873],[56.4536489205788,-20.76732095466354],[56.45135903508837,-20.75845572366961],[56.40606959206033,-20.540389063777194],[56.488470172,-20.604660541],[56.582180755,-20.828316241],[56.544780108,-20.739053453],[55.708903414,-16.714344237]],[[56.726055461,-21.887858717],[56.682432459,-21.56660403],[56.695667931,-21.465571629],[56.617804891,-21.090664544],[56.582180755,-20.828316241],[56.726055461,-21.887858717]]],"type":"Polygon"}$previous$::jsonb) THEN RAISE EXCEPTION 'ROAD_CHANGED_REQUIRES_REVIEW'; END IF;
 SELECT array_agg(id) INTO ids FROM public.map_entities WHERE project_id=p AND (id=e OR public_identifier IN ('EXPORURAL-PASSAGEM-LESTE-01','EXPORURAL-PASSAGEM-LESTE-02','Q-R-41','Q-R-44','Q-R-45','Q-R-46','Q-R-49','Q-R-52','Q-R-53','Q-R-54')) AND NOT is_archived;
 before_state:=pg_temp.exporural_state(p,ids);
 IF EXISTS(SELECT 1 FROM public.commercial_lots l JOIN public.map_entities me ON me.id=l.entity_id JOIN public.map_entity_geometries g ON g.entity_id=me.id AND g.is_current WHERE me.project_id=p AND NOT me.is_archived AND l.archived_at IS NULL AND ST_Area(ST_Intersection(ST_GeomFromGeoJSON(pavement),ST_GeomFromGeoJSON(g.geometry)))>0.0000001) THEN RAISE EXCEPTION 'PAVEMENT_INTERSECTS_COMMERCIAL_PARCEL'; END IF;
 INSERT INTO public.map_reference_migration_snapshots(org_id,project_id,area_code,source_revision,payload_hash,status,snapshot,created_by)
 VALUES('985888b8-155f-4bbe-b6b9-6bef2893d99b',p,'EXPORURAL_SURFACES',rev,md5(pavement::text),'PENDING',before_state,auth.uid()) RETURNING id INTO sid;
 UPDATE public.map_entity_geometries SET geometry=pavement,version=version+1,change_reason=rev,updated_at=now() WHERE entity_id=e AND is_current;
 UPDATE public.map_entity_geometries SET extrusion_height=.032,version=version+1,change_reason=rev,updated_at=now() WHERE entity_id IN (SELECT id FROM public.map_entities WHERE project_id=p AND public_identifier IN ('EXPORURAL-PASSAGEM-LESTE-01','EXPORURAL-PASSAGEM-LESTE-02') AND NOT is_archived) AND is_current AND extrusion_height<>.032;
 UPDATE public.map_entities me SET metadata=metadata||jsonb_build_object('surfaceRevision',rev,'geometryHash',encode(sha256(convert_to(g.geometry::text,'UTF8')),'hex'),'revisionGeometryVersion',g.version) FROM public.map_entity_geometries g WHERE me.id=g.entity_id AND g.is_current AND me.id=ANY(ids) AND me.classification='ROAD';
 -- The initial physical template was a corner. Internal children have no second
 -- street frontage; do not copy its corner flag or approve a corner premium.
 UPDATE public.commercial_lots SET is_corner=false WHERE entity_id=ANY(ids) AND public_identifier IN ('Q-R-41','Q-R-44','Q-R-45','Q-R-46','Q-R-49','Q-R-52','Q-R-53','Q-R-54');
 after_state:=pg_temp.exporural_state(p,ids);
 IF pg_temp.exporural_business(before_state)<>pg_temp.exporural_business(after_state) THEN RAISE EXCEPTION 'COMMERCIAL_LINK_CHANGED'; END IF;
 UPDATE public.map_reference_migration_snapshots SET status='APPLIED',applied_at=now(),apply_result=jsonb_build_object('entityIds',ids,'afterStateMd5',md5(after_state::text),'commercialPolygonsChanged',0,'businessLinksUnchanged',true,'addedAsphaltLocalSq',1.9083152765619842) WHERE id=sid;
 INSERT INTO public.map_activity_logs(org_id,project_id,entity_id,action,reason,before_state,after_state,actor_user_id) VALUES('985888b8-155f-4bbe-b6b9-6bef2893d99b',p,e,'EXPORURAL_SURFACE_CORRECTED',rev,jsonb_build_object('snapshotId',sid),jsonb_build_object('commercialPolygonsChanged',0),auth.uid());
END;
$surface$;
